    if(f->ctx->arch==HB_ARCH_X86)check(!memcmp(&observed.x87_64,&before->x87_64,sizeof(before->x87_64)),"inactive x64 x87 state unchanged");
    check(observed.mxcsr==before->mxcsr,"MXCSR unchanged");
    check(!memcmp(observed.ymm_hi,before->ymm_hi,sizeof(before->ymm_hi))&&!memcmp(observed.zmm_hi,before->zmm_hi,sizeof(before->zmm_hi))&&!memcmp(observed.k,before->k,sizeof(before->k))&&!memcmp(observed.xmm_ext,before->xmm_ext,sizeof(before->xmm_ext))&&!memcmp(observed.ymm_hi_ext,before->ymm_hi_ext,sizeof(before->ymm_hi_ext))&&!memcmp(observed.zmm_hi_ext,before->zmm_hi_ext,sizeof(before->zmm_hi_ext)),"upper vectors/opmasks unchanged");
    check(observed.fs_base==before->fs_base&&observed.gs_base==before->gs_base&&observed.seg_cs==before->seg_cs&&observed.seg_ds==before->seg_ds&&observed.seg_es==before->seg_es&&observed.seg_fs==before->seg_fs&&observed.seg_gs==before->seg_gs&&observed.seg_ss==before->seg_ss,"segments unchanged");
