static void run_case(fixture_t *f,const char *name,const raw_t *input,const answer_t *answer,unsigned top,unsigned pc,unsigned rc,unsigned pm,unsigned host,unsigned hf,unsigned group,unsigned valid,unsigned im,unsigned nan_class)
{
    snprintf(phase,sizeof(phase),"%s %s %s TOP=%u PC=%u RC=%u PM=%u host=%u flags=%u group=%u cache=%u IM=%u",f->ctx->arch==HB_ARCH_X86?"x86":"x64",f->jit?"JIT":"interp",name,top,pc,rc,pm,host,hf,group,valid,im);
    seed(f,input,top,pc,rc,pm,hf,group,valid,im);hb_context_t before;memcpy(&before,f->ctx,sizeof(before));
    if(!seed_host(host,hf,group,input))return;
    host_t wanted=host_state();hb_exec_result_t out={0};hb_result_t result=f->jit?hb_jit_runtime_run(f->jit,f->func,&out):hb_interpreter_run(f->interp,f->func,&out);host_t actual=host_state();
    ++executions;++group_calls[group];check_kind(same_host(wanted,actual),"host RC/status and full ARM FPCR/FPSR unchanged",HOST);
    if(group==EMPTY&&!im)check_kind((result==HB_OK||result==HB_ERR_EXEC_FAULT)&&out.result==HB_ERR_EXEC_FAULT&&out.faulted&&!out.timed_out,"IM0 empty faults before sqrt/store",EXECUTION);
    else check_kind(result==HB_OK&&out.result==HB_OK&&!out.faulted&&!out.timed_out&&out.steps_executed&&out.blocks_executed&&f->ctx->pc==CODE+2,"single FSQRT completes without pop",EXECUTION);
    check_state(f,&before,answer,group,im,nan_class);
}
static int native_present(fixture_t *f)
{if(!f->jit||!f->jit->block_cache)return 0;hb_block_cache_t *c=f->jit->block_cache;for(size_t i=0;i<c->size;++i)if(c->entries[i].valid&&c->entries[i].guest_addr==CODE&&c->entries[i].native_code&&c->entries[i].native_size)return 1;return 0;}
static void check_ir(fixture_t *f)
{
    unsigned count=0;if(!check_kind(f->func->cfg!=NULL,"IR container present",DECODE))return;
    for(size_t b=0;b<f->func->cfg->block_count;++b){hb_ir_block_t *block=f->func->cfg->blocks[b];for(size_t i=0;i<block->instr_count;++i){hb_ir_instr_t *ir=&block->instrs[i];if(ir->op!=HB_IR_X87_FSQRT)continue;++count;check_kind(ir->guest_addr==CODE,"FSQRT IR source address; unused operands not asserted",DECODE);}}
    check_kind(count==1,"exactly one implicit ST0 FSQRT IR",DECODE);
}
